// path: apps/web/src/components/common/ThemeToggle.tsx
"use client";

import { useTheme } from "next-themes";
import { useEffect, useMemo, useState } from "react";

export default function ThemeToggle() {
  const { resolvedTheme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);

  const isDark = useMemo(() => resolvedTheme === "dark", [resolvedTheme]);

  if (!mounted) {
    return (
      <button
        type="button"
        className="inline-flex h-10 items-center rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-3 text-sm font-medium text-[var(--text-soft)]"
        disabled
      >
        ...
      </button>
    );
  }

  return (
    <button
      type="button"
      onClick={() => setTheme(isDark ? "light" : "dark")}
      className="inline-flex h-10 items-center gap-2 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-soft)] px-3 text-sm font-medium text-[var(--text-main)] transition hover:bg-[var(--bg-card-strong)]"
      aria-label={isDark ? "Chuyển sang chế độ sáng" : "Chuyển sang chế độ tối"}
      title={isDark ? "Chuyển sang chế độ sáng" : "Chuyển sang chế độ tối"}
    >
      <span className="text-base">{isDark ? "🌙" : "☀️"}</span>
      <span>{isDark ? "Tối" : "Sáng"}</span>
    </button>
  );
}